import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const SHARE_PERMISSIONS = ['열람', '수정'];
const SHARE_METHODS = ['쪽지', '이메일'];

function isId(value: unknown): boolean {
  return (typeof value === 'number' || typeof value === 'string') && /^[0-9]+$/.test(String(value).trim());
}

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || String(value).trim() === '';
}

@Controller('api/v1')
export class FnSfr04102Controller {
  @Post('/office-document-shares')
  @HttpCode(200)
  async createOfficeDocumentShare(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);

    if (isBlank(data.sharedEmployeeId) || isBlank(data.permissionType)) {
      throw new ApiError(422, 'SHARE_REQUIRED_VALUE_MISSING', '공유 대상자와 공유 권한을 지정해 주세요.');
    }
    if (!isId(data.officeDocumentId) || !isId(data.sharedEmployeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서와 공유 대상자 값이 올바르지 않습니다.');
    }
    if (typeof data.permissionType !== 'string' || !SHARE_PERMISSIONS.includes(data.permissionType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 권한은 열람 또는 수정이어야 합니다.');
    }
    if (typeof data.shareMethod !== 'string' || !SHARE_METHODS.includes(data.shareMethod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 방식은 쪽지 또는 이메일이어야 합니다.');
    }
    if (data.shareMessage !== undefined && data.shareMessage !== null && typeof data.shareMessage !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 메시지 형식이 올바르지 않습니다.');
    }
    const shareMessage = isBlank(data.shareMessage) ? null : String(data.shareMessage);

    return transaction(async (db) => {
      const documents = await db.query(
        'SELECT office_document_id AS "officeDocumentId", author_id AS "authorId" FROM office_document WHERE office_document_id = CAST(:documentId AS bigint)',
        { documentId: String(data.officeDocumentId).trim() },
      );
      if (documents.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
      }

      // 가정: 공유 권한은 문서 작성자 또는 '수정' 권한을 공유받은 사용자에게 있다 (수정은 열람을 포함).
      let canShare = String(documents[0].authorId) === user.id;
      if (!canShare) {
        const grants = await db.query(
          "SELECT office_document_share_id AS \"id\" FROM office_document_share WHERE office_document_id = CAST(:documentId AS bigint) AND shared_employee_id = CAST(:userId AS bigint) AND permission_type = '수정'",
          { documentId: String(data.officeDocumentId).trim(), userId: user.id },
        );
        canShare = grants.length > 0;
      }
      if (!canShare) {
        throw new ApiError(409, 'OFFICE_DOCUMENT_SHARE_FORBIDDEN', '해당 문서를 공유할 권한이 없습니다.');
      }

      const employees = await db.query(
        'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId: String(data.sharedEmployeeId).trim() },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '공유 대상자를 찾을 수 없습니다.');
      }

      // 같은 문서·대상자 조합은 한 행이므로 이미 공유된 경우 권한·방식·메시지를 갱신한다.
      const rows = await db.query(
        'INSERT INTO office_document_share (office_document_id, shared_employee_id, permission_type, share_method, share_message, hidden_by_recipient, created_at, updated_at) '
          + 'VALUES (CAST(:documentId AS bigint), CAST(:employeeId AS bigint), :permissionType, :shareMethod, :shareMessage, false, now(), now()) '
          + 'ON CONFLICT (office_document_id, shared_employee_id) DO UPDATE SET permission_type = EXCLUDED.permission_type, share_method = EXCLUDED.share_method, share_message = EXCLUDED.share_message, hidden_by_recipient = false, updated_at = now() '
          + 'RETURNING office_document_share_id AS "officeDocumentShareId", shared_employee_id AS "sharedEmployeeId", permission_type AS "permissionType"',
        {
          documentId: String(data.officeDocumentId).trim(),
          employeeId: String(data.sharedEmployeeId).trim(),
          permissionType: data.permissionType,
          shareMethod: data.shareMethod,
          shareMessage,
        },
      );

      // 가정: 쪽지·이메일 발송 모듈이 없어 공유 저장이 끝나면 전달 요청이 접수된 것으로 본다.
      const notified = true;
      return {
        officeDocumentShareId: rows[0].officeDocumentShareId,
        sharedEmployeeId: rows[0].sharedEmployeeId,
        permissionType: rows[0].permissionType,
        notified,
      };
    });
  }
}

