import { useState } from 'react';
import {
  PageProps,
  Row,
  call,
  Badge,
  Tiles,
  Band,
  DataTable,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
} from '../kit';

export default function FnSfr04102Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [officeDocumentId, setOfficeDocumentId] = useState<number | string>('');
  const [sharedEmployeeId, setSharedEmployeeId] = useState<number | string>('');
  const [permissionType, setPermissionType] = useState('');
  const [shareMethod, setShareMethod] = useState('');
  const [shareMessage, setShareMessage] = useState('');

  function openDrawer() {
    setOfficeDocumentId('');
    setSharedEmployeeId('');
    setPermissionType('');
    setShareMethod('');
    setShareMessage('');
    setOpen(true);
  }

  async function submit() {
    if (officeDocumentId === '') {
      throw new Error('문서를 선택해 주세요.');
    }
    if (sharedEmployeeId === '') {
      throw new Error('공유 대상자를 선택해 주세요.');
    }
    if (permissionType === '') {
      throw new Error('공유 권한을 선택해 주세요.');
    }
    if (shareMethod === '') {
      throw new Error('공유 방식을 선택해 주세요.');
    }
    const body: Row = { officeDocumentId, sharedEmployeeId, permissionType, shareMethod };
    if (shareMessage.trim() !== '') {
      body.shareMessage = shareMessage;
    }
    const result = await call('POST', '/office-document-shares', role, body);
    setResults([{ ...result, officeDocumentId }, ...results]);
    setOpen(false);
    notify('문서를 공유했습니다.');
  }

  const notifiedCount = results.filter((r) => r.notified === true).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>공유 현황</h2>
        <Tiles
          items={[
            ['이번 화면 공유', results.length],
            ['전달 완료', notifiedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>공유 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>문서 공유</button>
        </Band>
        <DataTable
          rows={results}
          empty="공유한 문서가 없습니다."
          columns={[
            { key: 'officeDocumentShareId', label: '웹오피스 문서 공유 ID' },
            {
              key: 'officeDocumentId',
              label: '문서',
              render: (r) => <RefName table="office_document" role={role} value={r.officeDocumentId} />,
            },
            {
              key: 'sharedEmployeeId',
              label: '공유 대상자',
              render: (r) => <RefName table="employee" role={role} value={r.sharedEmployeeId} />,
            },
            {
              key: 'permissionType',
              label: '공유 권한',
              render: (r) => <Badge value={r.permissionType} />,
            },
            {
              key: 'notified',
              label: '쪽지 또는 이메일 전달 성공 여부',
              render: (r) => <Badge value={r.notified === true ? '완료' : '실패'} />,
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title="문서 공유" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="공유">
            <Field label="문서" required>
              <LookupSelect
                table="office_document"
                role={role}
                value={officeDocumentId}
                onChange={setOfficeDocumentId}
              />
            </Field>
            <Field label="공유 대상자" required>
              <LookupSelect
                table="employee"
                role={role}
                value={sharedEmployeeId}
                onChange={setSharedEmployeeId}
              />
            </Field>
            <Field label="공유 권한" required hint="수정 권한은 열람을 포함합니다.">
              <Select
                value={permissionType}
                onChange={setPermissionType}
                options={[['열람', '열람'], ['수정', '수정']]}
              />
            </Field>
            <Field label="공유 방식" required>
              <Select
                value={shareMethod}
                onChange={setShareMethod}
                options={[['쪽지', '쪽지'], ['이메일', '이메일']]}
              />
            </Field>
            <Field label="공유 메시지" wide>
              <TextInput value={shareMessage} onChange={setShareMessage} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
